const SO_NGAY_LUI = 7;
const ngayGioiHan = new Date(Date.now() - SO_NGAY_LUI * 86400000)
  .toISOString()
  .slice(0, 10);

// GitHub OR chỉ áp dụng cho search terms, không áp dụng giữa các qualifier topic:.
// Mỗi topic thay thế phải là một query riêng; node sau gộp và loại trùng theo repo.id.
const DANH_SACH_CHU_DE = [
  { chude: 'AI Agents', topic: 'ai-agent', saoToiThieu: 10 },
  { chude: 'MCP', topic: 'mcp', saoToiThieu: 5 },
  { chude: 'MCP', topic: 'model-context-protocol', saoToiThieu: 5 },
  { chude: 'RAG', topic: 'rag', saoToiThieu: 10, ngonNgu: 'python' },
  { chude: 'Modern Data Stack', topic: 'duckdb', saoToiThieu: 10 },
  { chude: 'Modern Data Stack', topic: 'apache-iceberg', saoToiThieu: 10 }
];

return DANH_SACH_CHU_DE.map(({ chude, topic, saoToiThieu, ngonNgu }) => ({
  json: {
    chude,
    truyvan: `topic:${topic}${ngonNgu ? ` language:${ngonNgu}` : ''} created:>${ngayGioiHan} stars:>${saoToiThieu} fork:false archived:false`
  }
}));

// Lưu ý: static data chỉ được đọc ở đây để loại trừ repo đã gửi trong quá khứ.
// Việc commit/ghi nhớ ID mới chỉ diễn ra ở node cuối sau khi Gmail đã gửi thành công.
const staticData = $getWorkflowStaticData('global');
const daGuiRepoIds = staticData.daGuiRepoIds || [];

const SO_LUONG_TOI_DA = 15;
const daGapTrongLanNay = new Set();
const danhSachRepoHopLe = [];

for (const item of $input.all()) {
  for (const repo of item.json?.items || []) {
    if (!repo.id || daGapTrongLanNay.has(repo.id)) continue;
    if (daGuiRepoIds.includes(repo.id)) continue;

    const moTa = (repo.description || '').trim();
    if (repo.fork || repo.archived || moTa.length < 20) continue;

    daGapTrongLanNay.add(repo.id);
    danhSachRepoHopLe.push({
      id: repo.id,
      ten: repo.full_name,
      duongDan: repo.html_url,
      moTa,
      stars: repo.stargazers_count || 0,
      forks: repo.forks_count || 0,
      ngonNgu: repo.language || 'Không xác định',
      chuDe: (repo.topics || []).slice(0, 5).join(', ')
    });
  }
}

danhSachRepoHopLe.sort((a, b) => b.stars - a.stars);
const topRepo = danhSachRepoHopLe.slice(0, SO_LUONG_TOI_DA);

const vanBanNguCanh = topRepo
  .map((repo, i) => `${i + 1}. [${repo.ten}](${repo.duongDan})\n   - Stars: ${repo.stars} | Ngôn ngữ: ${repo.ngonNgu}\n   - Thẻ: ${repo.chuDe || 'Không'}\n   - Mô tả gốc: ${repo.moTa}`)
  .join('\n\n');

return [{
  json: {
    tongSoRepo: topRepo.length,
    ngayTongHop: new Date().toISOString().slice(0, 10),
    topRepoIds: topRepo.map(repo => repo.id),
    vanBanNguCanh
  }
}];

// Chỉ ghi nhận ID vào staticData sau khi Gmail đã gửi thành công.
// Nếu node OpenAI hoặc Gmail bị lỗi, workflow dừng lại và ID sẽ không bị mất ở lần chạy kế tiếp.
const staticData = $getWorkflowStaticData('global');
staticData.daGuiRepoIds ??= [];

const topRepoIds = $('Lọc, loại trùng & gom nội dung').first().json?.topRepoIds || [];

if (topRepoIds.length > 0) {
  staticData.daGuiRepoIds = [
    ...new Set([...staticData.daGuiRepoIds, ...topRepoIds])
  ].slice(-500);
}

return [{
  json: {
    trangThai: 'Đã gửi email và lưu static data thành công',
    soRepoMoiDaGhiNhan: topRepoIds.length,
    tongSoRepoDaGhiNhan: staticData.daGuiRepoIds.length,
    thoiGianGhiNhan: new Date().toISOString()
  }
}];
